function loadImage(data){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=data;});}
$('imagebutton').onclick=()=>$('imagefile').click();$('imagefile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)return notice('اختر صورة أقل من 10 ميغابايت.');try{const data=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.onerror=j;reader.readAsDataURL(f);});const im=await loadImage(data);pendingImage={data,ratio:im.height/im.width};setTool('image');notice('اضغط على الصفحة لوضع الصورة.');}catch{notice('تعذر قراءة الصورة.');}e.target.value='';};
const sig=$('sig'),sc=sig.getContext('2d');let signing=false,signatureHasInk=false;const sp=e=>{const r=sig.getBoundingClientRect();return [(e.clientX-r.left)*sig.width/r.width,(e.clientY-r.top)*sig.height/r.height];};sig.onpointerdown=e=>{signing=true;sig.setPointerCapture(e.pointerId);sc.beginPath();sc.moveTo(...sp(e));};sig.onpointermove=e=>{if(!signing)return;sc.strokeStyle='#16363c';sc.lineWidth=3;sc.lineCap='round';sc.lineTo(...sp(e));sc.stroke();signatureHasInk=true;};sig.onpointerup=()=>signing=false;sig.onpointercancel=()=>signing=false;$('signaturebutton').onclick=()=>$('sigdialog').showModal();$('clearsig').onclick=()=>{sc.clearRect(0,0,sig.width,sig.height);signatureHasInk=false;};$('closesig').onclick=()=>$('sigdialog').close();$('usesig').onclick=()=>{if(!signatureHasInk)return notice('ارسم توقيعًا أولًا.');pendingImage={data:sig.toDataURL(),ratio:sig.height/sig.width};$('sigdialog').close();setTool('image');notice('اضغط على الصفحة لوضع التوقيع.');};
$('download').onclick=async()=>{if(busy||!pdf)return;if(inlineSession)inlineSession.close(true);if(objectSession)objectSession.close(true);busy=true;$('editor').inert=true;$('download').disabled=true;try{const source=await PDFLib.PDFDocument.load(bytes),out=await PDFLib.PDFDocument.create();for(let i=0;i<pages.length;i++){notice(`جارٍ تجهيز الصفحة ${i+1} من ${pages.length}…`);const p=pages[i];if(!p.edits.length){const [copy]=await out.copyPages(source,[p.source]);copy.setRotation(PDFLib.degrees((copy.getRotation().angle+p.rotation)%360));out.addPage(copy);}else{const src=await pdf.getPage(p.source+1);const angle=(src.rotate+p.rotation)%360;const base=src.getViewport({scale:1,rotation:angle});const scale=Math.min(2,Math.sqrt(16000000/(base.width*base.height)));const vp=src.getViewport({scale,rotation:angle});const c=document.createElement('canvas');c.width=Math.ceil(vp.width);c.height=Math.ceil(vp.height);const cx=c.getContext('2d');await src.render({canvasContext:cx,viewport:vp}).promise;await paintEdits(cx,p,scale);const image=await out.embedPng(c.toDataURL('image/png'));out.addPage([base.width,base.height]).drawImage(image,{x:0,y:0,width:base.width,height:base.height});c.width=0;c.height=0;}}const data=await out.save();const url=URL.createObjectURL(new Blob([data],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=$('filename').textContent.replace(/\.pdf$/i,'')+'-edited.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notice('تم تجهيز الملف وتنزيله.');}catch(e){console.error(e);notice('تعذّر تصدير الملف. جرّب ملفًا أصغر أو تراجع عن آخر تعديل.');}finally{busy=false;$('editor').inert=false;$('download').disabled=false;}};

if(typeof location!=='undefined'&&location.hostname.endsWith('.github.io')){const owner=location.hostname.split('.')[0],repo=location.pathname.split('/').filter(Boolean)[0]||owner+'.github.io';$('feedback').href='https://github.com/'+owner+'/'+repo+'/issues/new/choose';$('feedback').hidden=false;}
